import { useText } from '@adobe-commerce/elsie/i18n';
import { classes, Container } from '@adobe-commerce/elsie/lib';
import { QuickOrderVariantsGrid as QuickOrderVariantsGridComponent } from '@/b2b-quick-order/components/QuickOrderVariantsGrid/QuickOrderVariantsGrid';
import { QuickOrderVariantsActions } from '@/b2b-quick-order/components/QuickOrderVariantsActions/QuickOrderVariantsActions';
import { useQuickOrderVariantsData } from '@/b2b-quick-order/hooks/useQuickOrderVariantsData';
import { QuickOrderVariantsGridProps } from '@/b2b-quick-order/types/quickOrderVariantsGrid.types';

export const QuickOrderVariantsGrid: Container<QuickOrderVariantsGridProps> = ({
  className,
  initialVariants,
  onVariantsLoaded,
  onSelectedVariantsChange,
  debounceMs = 300,
  initialLoading,
  visibleVariantsLimit = 10,
  columns,
  slots,
}) => {
  const t = useText({
    imageColumn: 'QuickOrder.VariantsGrid.imageColumn',
    skuColumn: 'QuickOrder.VariantsGrid.skuColumn',
    availabilityColumn: 'QuickOrder.VariantsGrid.availabilityColumn',
    priceColumn: 'QuickOrder.VariantsGrid.priceColumn',
    quantityColumn: 'QuickOrder.VariantsGrid.quantityColumn',
    subtotalColumn: 'QuickOrder.VariantsGrid.subtotalColumn',
    clearButton: 'QuickOrder.VariantsGrid.clearButton',
    saveToCsvButton: 'QuickOrder.VariantsGrid.saveToCsvButton',
    collectDataButton: 'QuickOrder.VariantsGrid.collectDataButton',
    inStock: 'QuickOrder.VariantsGrid.inStock',
    outOfStock: 'QuickOrder.VariantsGrid.outOfStock',
    quantityLabel: 'QuickOrder.VariantsGrid.quantityLabel',
    showAll: 'QuickOrder.VariantsGrid.showAll',
    showLess: 'QuickOrder.VariantsGrid.showLess',
  });

  const {
    variants,
    loading,
    updateQuantity,
    clearAllQuantities,
    exportToCsv,
    collectTableData,
    variantsWithQuantity,
  } = useQuickOrderVariantsData({
    initialVariants,
    onVariantsLoaded,
    onSelectedVariantsChange,
    debounceMs,
    initialLoading,
  });

  if (variants.length === 0 && !loading) {
    return null;
  }

  return (
    <div
      className={classes([
        'b2b-quick-order-variants-grid-container',
        className,
      ])}
      data-testid="variants-grid-container"
    >
      <QuickOrderVariantsActions
        t={t}
        onClear={clearAllQuantities}
        onSaveToCsv={exportToCsv}
        onCollectData={collectTableData}
        isDisabled={loading}
        variantsCount={variantsWithQuantity}
        slots={slots}
      />

      <QuickOrderVariantsGridComponent
        t={t}
        variants={variants}
        loading={loading}
        onQuantityChange={updateQuantity}
        visibleVariantsLimit={visibleVariantsLimit}
        columns={columns}
        slots={slots}
      />
    </div>
  );
};
